import { createHash, randomBytes } from 'crypto'
import { createAdminClient } from '@/lib/supabase/admin'

export type BotName = 'app_bot' | 'financial_bot'

export type BotIdentity = { botName: BotName; tokenId: string }

// Tokens are never stored or logged as plaintext anywhere - only this hash
// ever reaches the database (bot_tokens.token_hash) or a log line. SHA-256
// of a 256-bit random value has no practical reversal/collision risk here;
// this isn't a password (no per-user salt needed) since every token is
// already high-entropy and generated by us, never user-chosen.
function hashToken(token: string): string {
  return createHash('sha256').update(token).digest('hex')
}

// Generates a brand-new bot token. The plaintext is returned ONCE to the
// caller (the admin UI that shows it to Jesse a single time - see
// app/bot-tokens/page.tsx) and is never written anywhere else; only the
// hash is persisted. Prefixed per bot purely so a token is recognizable at
// a glance if it ever shows up somewhere it shouldn't (e.g. truncated in a
// third-party tool's own logs) - the prefix carries no security weight.
export function generateBotToken(botName: BotName): { token: string; tokenHash: string } {
  const prefix = botName === 'app_bot' ? 'appbot' : 'finbot'
  const secret = randomBytes(32).toString('base64url')
  const token = `${prefix}_${secret}`
  return { token, tokenHash: hashToken(token) }
}

// Verifies the Authorization: Bearer <token> header against bot_tokens,
// and requires the caller to be the SPECIFIC bot the route names - an App
// Bot token must never authenticate a Financial Bot route or vice versa,
// even though both are valid, unrevoked tokens. Returns null on any
// failure (missing header, unknown token, wrong bot, revoked) - every
// /api/bot/* route must itself return 401/403 when this comes back null;
// this function never throws and never grants access by default.
export async function verifyBotToken(request: Request, requiredBot: BotName): Promise<BotIdentity | null> {
  const auth = request.headers.get('authorization') || ''
  const match = auth.match(/^Bearer\s+(.+)$/i)
  if (!match) return null
  const token = match[1].trim()
  if (!token) return null

  const admin = createAdminClient()
  if (!admin) return null

  const tokenHash = hashToken(token)
  const { data: row } = await admin
    .from('bot_tokens')
    .select('id, bot_name, revoked_at')
    .eq('token_hash', tokenHash)
    .is('revoked_at', null)
    .maybeSingle()
  if (!row || row.bot_name !== requiredBot) return null

  // Best-effort freshness marker for the admin token-management UI - never
  // blocks or slows the actual request if this update fails.
  void admin.from('bot_tokens').update({ last_used_at: new Date().toISOString() }).eq('id', row.id)

  return { botName: row.bot_name as BotName, tokenId: row.id as string }
}
